{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "Each window's level, per sensor, over the recording time.",
  "mark": {
    "type": "line",
    "point": true
  },
  "encoding": {
    "x": {
      "field": "recorded_at",
      "type": "temporal",
      "title": "Time"
    },
    "y": {
      "field": "level_dbfs",
      "type": "quantitative",
      "title": "Level (dBFS)"
    },
    "color": {
      "field": "sensor",
      "type": "nominal",
      "title": "Sensor"
    }
  }
}
